from svgkit import *
from printer_figs import WIDE
F1,F2,F3,F4,F5=WIDE
S=dict(slug='find-printer-ip-address',date='2026-10-31',date_label='',plan='P13',
title="How to Find a Printer's IP Address on Any Device",headline="How to Find a Printer's IP Address on Windows, Mac, Linux, Phone or Router",
desc="Find out your printer's IP address from its screen, Windows, Mac, Linux, a phone app or your router. Brother, HP, Epson and Canon steps, with diagrams.",
kw=["how to find printer ip address","how to check printer ip address","how do i find my printer's ip address","how do i find out my printer's ip address","find printer ip address","printer ip address windows 11","printer ip address mac","how to find brother printer ip address","how to add printer using ip address"],
about="Printer IP address",section='Networking How-To',crumb="Find a Printer's IP Address",
h1='How to Find a <span class="ndic-highlight">Printer\'s IP Address</span>',tagline="Find out your printer's address from its own screen, your computer, a phone app or your router, with steps for Brother, HP, Epson and Canon.",kicker='Printers &amp; Devices',cta='Pick My Device',
qa_title="Four reliable ways to find a printer's IP address",
qa_body="The fastest way is the printer's own screen: open its Network menu or print a configuration page. On Windows, open Printer properties and read the Ports tab, or the Web Services tab for a WSD printer. On Mac or Linux, run lpstat -v. Your router's device list also shows it. A printer on USB only has no IP address.",
og_title='How to Find a <span style="color:#38bdf8">Printer\'s IP Address</span>',og_sub='Printer screen, Windows, Mac, Linux, phone app or your router',og_chip='192 . 168 . 1 . <span style="color:#38bdf8">50</span>',
card_desc="Find a printer's IP address from the printer screen, Windows, Mac, Linux, a phone app or your router, with Brother, HP, Epson and Canon steps.",
picker_label='Choose your device',picker_note="Menu names vary by printer maker and model. The pattern is the same: look for Network, Wi-Fi or Status, then an item called IP address.",
picker=[('Printer screen (any model)',['On the printer, open <strong>Settings</strong> or <strong>Setup</strong>, then <strong>Network</strong> or <strong>Wi-Fi</strong>.','Choose <strong>Network status</strong>, <strong>Wireless summary</strong> or <strong>Print network configuration</strong>.','Read the line labelled <strong>IP address</strong>. A value starting 169.254 means the printer did not get an address from the router.','No screen? Print the network configuration page with the button your printer manual names.']),
('Windows 10 / 11',['Open <strong>Settings > Bluetooth &amp; devices > Printers &amp; scanners</strong> and select the printer.','Choose <strong>Printer properties</strong> and open the <strong>Ports</strong> tab. The checked port shows the address. If the port name starts with <strong>WSD-</strong>, the printer uses a WSD port, so open the <strong>Web Services</strong> tab instead.','Or run in PowerShell: <code>Get-Printer | Select Name,PortName</code> then <code>Get-PrinterPort | Select Name,PrinterHostAddress</code>. The address column can be empty for a WSD port.']),
('Mac',['Open <strong>Terminal</strong> and run <code>lpstat -v</code>.','Find your printer in the output. The address appears in the device URI, for example <code>ipp://192.168.1.50/ipp/print</code>.','If the URI holds a name such as <code>printer.local</code>, run <code>ping -c 1 printer.local</code> to see its address. A <code>dnssd://</code> service name does not hold the address: use the printer screen or the router list.']),
('Linux',['Run <code>lpstat -v</code> in a terminal.','Read the address inside the device URI (for example <code>ipp://192.168.1.50/ipp/print</code> or <code>socket://192.168.1.50:9100</code>).','Alternatively open <code>http://localhost:631/printers</code> if the CUPS web interface is enabled.']),
('iPhone, iPad or Android',["A phone does not list other devices' addresses. Use the printer maker's app: in the HP app, tap your printer, then <strong>Network Information</strong>. Other makers' apps usually show network details in the printer or settings screen.",'AirPrint printers often appear by name only. If the app does not show an address, use the printer screen or the router method instead.']),
('Router (works for any printer)',['Open your router\'s admin page (see the <a href="/learn/find-router-ip-address">router IP guide</a>) and sign in.','Open <strong>Connected devices</strong>, <strong>DHCP clients</strong> or <strong>Device list</strong>.','Find the printer by its name or manufacturer. The address is on the same row.'])],
panel=dict(eyebrow='Network Identity panel',h3='See what the internet sees',p='A printer\'s address is private and only works inside your home. The <a href="/intelligence/network-identity">Network Identity panel</a> shows your public address, which is a different thing. Compare them in <a href="/learn/what-is-an-ip-address">What Is an IP Address?</a>.',href='/intelligence/network-identity',btn='Open Network Identity'),
sections=[
('ways','Pick the Fastest Way to Find It','''<p>You only need one method, and the best one depends on what you can reach right now. The printer screen needs no computer. Windows, Mac and Linux read the address from the printer's entry on the computer. A phone app shows it on a phone. The router's device list works even when the printer has no display. A printer connected only by a USB cable is not on the network, so it has no IP address.</p>'''+fig(F1,'Start from what you can reach: the printer, a computer that prints to it, a phone or the router.')+table('Methods compared',['Method','Needs','Works with no display','Effort'],[['Printer screen','Access to the printer','No','Lowest'],["Maker's app",'A phone and a printer set up in the app','Yes','Low'],['Windows Properties','A Windows PC with the printer added','Yes','Low'],['Mac or Linux terminal','A Mac or Linux computer with the printer added','Yes','Low'],['Router device list','Router login','Yes','Medium']])+'''<p>The router route needs the router's own address first. Our <a href="/learn/find-router-ip-address">guide to finding your router's IP address</a> shows how.</p>'''),
('where','Where a Printer Gets Its Address','''<p>A network printer gets a private address from your router, just like a laptop does, usually through DHCP, the protocol defined in RFC 2131. Because the address is private, it only works on your own network. If you are unsure what that means, read <a href="/learn/what-is-an-ip-address">what an IP address is</a> first.</p><p>The router can hand the printer a different address after a restart. Any device that saved the old address then sends print jobs to an address nobody answers.</p>'''+fig(F2,'The router gave the printer a new address after a restart. The laptop still sends jobs to the old one.')),
('windows','Windows 10 and 11','''<p>Windows stores the printer address in the port the printer uses, so the answer sits in the printer's properties.</p><ol class="ir-steps"><li>Open Settings, then Bluetooth &amp; devices, then Printers &amp; scanners, and select your printer.</li><li>Choose <strong>Printer properties</strong> and open the <strong>Ports</strong> tab.</li><li>Look at the checked port. If it shows an address, often written like <code class="ir-code">IP_192.168.1.50</code>, that is the printer's address.</li><li>If the port name starts with <code class="ir-code">WSD-</code>, the printer uses a WSD port and the name does not hold the address. Open the <strong>Web Services</strong> tab in the same window, where the address is listed.</li><li>No address on either tab? Use the printer screen method instead.</li></ol><p>The PowerShell commands in the picker give the same answer for a normal TCP/IP port. For a WSD port the address column can come back empty, which is why the Web Services tab matters.</p>'''),
('mac-linux','Mac and Linux','''<p>Both use CUPS. The command <code class="ir-code">lpstat -v</code> shows each printer and the device it is attached to. The device URI holds the address in forms such as <code class="ir-code">ipp://192.168.1.50/ipp/print</code>, <code class="ir-code">lpd://192.168.1.50/queue</code> or <code class="ir-code">socket://192.168.1.50:9100</code>.</p><p>If the URI holds a name such as <code class="ir-code">printer.local</code>, the printer is found by name, and pinging that name reveals the numeric address. A <code class="ir-code">dnssd://</code> URI carries a service name instead of an address, so use the printer screen or the router list in that case.</p>'''),
('report','From the Printer Itself','''<p>Nearly every network printer can print a configuration page, often called a network status sheet or LAN details page. It lists the address, subnet mask and gateway in one place, which is useful when you also need to fix a connection problem. Printers with a screen print it from the Network or Wi-Fi menu. Printers without a screen use a button, and the manual for your model names it.</p>'''+fig(F3,'The network configuration page: read the IP address line, and note the gateway is your router.')+'''<p>Some printers show 0.0.0.0 until they have finished getting an address. Wait a minute and print the page again.</p>'''),
('brands','Brother, HP, Epson and Canon Menus','''<p>Menu names differ by maker and model. These routes come from each maker's own support pages and fit many models, not all of them. If your screen looks different, print the network status or configuration page instead.</p>'''+table('Where the address sits on common makers',['Maker','On the printer','Also useful'],[['Brother','Print the Network Configuration Report. On models with a menu it sits under Print Reports, then Network Config. The report lists the IP address, subnet mask, node name and MAC address.','If it reads 0.0.0.0, wait a minute and print it again.'],['HP','Touchscreen: open Wireless Summary or Network Settings. No touchscreen: press the Information button to print an Information Report.','HP app: tap your printer, then Network Information.'],['Epson','Setup, then Wi-Fi/Network Settings, then Confirm Wi-Fi/Network Settings. The settings show on the screen, and a Start button prints a network status sheet.','Type the address into a browser to open the printer settings page.'],['Canon','PIXMA inkjets: Home, Setup, Device settings, LAN settings, Confirm LAN settings, then Print LAN details.','Type the address into a browser to open Remote UI.'],['Lexmark','Top left of the home screen, or the TCP/IP section of the Network/Ports menu.','A printed network setup page shows the same TCP/IP section.']])),
('phone','From a Phone or Tablet','''<p>A phone does not list other devices' addresses, so use the printer maker's app. In the HP app, tap your printer, then Network Information. Other makers' apps usually show network details in the printer or settings screen. AirPrint printers often appear by name only. If the app does not show an address, use the printer screen or the router list instead.</p>'''),
('stable','Keeping the Address From Changing','''<p>By default the router may hand the printer a different address after a restart, which breaks printing set up by address. Two fixes exist: a DHCP reservation on the router, or a static address set on the printer. The reservation is easier to undo and keeps all settings in one place. You set it in the router's admin page, which the <a href="/learn/find-router-ip-address">router IP guide</a> shows how to open. Method details are in <a href="/guides/how-to-find-ip-address-of-any-device">our guide to finding the IP address of any device</a>.</p>'''+fig(F4,'A reservation keeps the same address across restarts.')+table('Reservation versus static',['Feature','DHCP reservation','Static on the printer'],[['Set on','Router','Printer'],['Risk of address clash','Low','Higher if misconfigured'],['Survives a router change','No, redo it','Yes, if the range still matches'],['Best for','Most homes','Offices and fixed setups']])),
('add','Add a Printer by IP Address','''<p>Adding the printer by its address is the most reliable setup, because it does not depend on automatic discovery working each time.</p><ol class="ir-steps"><li><strong>Windows:</strong> open Settings, then Bluetooth &amp; devices, then Printers &amp; scanners, and choose Add device. Select <strong>Add manually</strong>, then <strong>Add a printer using an IP address or hostname</strong>. Choose <strong>TCP/IP Device</strong> as the device type, type the address and finish the wizard.</li><li><strong>Mac:</strong> open System Settings, then Printers &amp; Scanners, and choose Add Printer. Open the <strong>IP</strong> tab and type the address. Choose the protocol your printer supports: Internet Printing Protocol (IPP) for most modern printers, or Line Printer Daemon (LPD) for some older ones. Then add it.</li></ol><p>Use a reservation or static address first, as described above. A printer added by an address that later changes will show as offline.</p>'''),
('ping','Test the Connection With Ping','''<p>A ping test separates network faults from software faults. From a computer on the same network run <code class="ir-code">ping 192.168.1.50</code> on Windows, or <code class="ir-code">ping -c 4 192.168.1.50</code> on Mac and Linux, using your printer's address. Replies mean the printer is reachable. No reply usually means the computer cannot reach it, but some printers ignore ping, so also type the address into a web browser: most network printers answer with their own settings page.</p>'''+fig(F5,'A ping reply means the network is fine and the problem sits in the printer port or driver.')),
('trouble','Troubleshooting: Printer Offline or Not Found','''<p>Most printer problems come from a changed address, the wrong network, or the wrong port type. Match your symptom below.</p>'''+table('Printer troubleshooting',['Symptom','Likely cause','Fix'],[['Offline although powered on','The address changed after a restart','Print a configuration page, then update the port address (Printer properties, Ports, Configure Port) or add a reservation'],['Address starts 169.254','Printer got no address from the router','Check the Wi-Fi or cable, restart the printer and router, and confirm DHCP is on'],['Address shows 0.0.0.0','The printer has not finished getting an address','Wait a minute, then print the report again'],['Ports tab shows WSD- and no address','The printer was added with a WSD port','Read the address on the Web Services tab or the printer screen'],['Works for some devices only','Different network, guest Wi-Fi or client isolation','Put all devices on the same network and turn off AP or client isolation'],['Stopped after a new router','New router uses a different address range','Find the new address and re-add the printer'],['Found by name but not by address','Discovery by name works but the saved address is old','Add the printer again by its current address'],['Intermittent errors on Windows','A WSD port can lose the device','Switch to a Standard TCP/IP port with a fixed address']])+'<p>If every step fails, restart the printer, router and computer in that order, then run the ping test again before changing anything else.</p>')],
logic="Start from what you can reach, then follow the method that needs the least access. Brand menus and the phone route come next, then how to stop the address from changing so the lookup does not have to be repeated.",
method='Windows, Mac and CUPS steps follow Microsoft, Apple and CUPS documentation. Printer menu paths come from Brother, HP, Epson, Canon and Lexmark support pages and vary by model, so the page also says how to print the status sheet. WSD- port names and the Web Services tab come from Microsoft Q&amp;A answers written by community members, not a Microsoft reference page, and the AirPrint remark comes from a vendor blog. Steps were not run on every printer model.',
cites=[("RFC 8011: Internet Printing Protocol/1.1 (IPP)",'https://www.rfc-editor.org/rfc/rfc8011'),("Microsoft Learn: Get-PrinterPort",'https://learn.microsoft.com/en-us/powershell/module/printmanagement/get-printerport'),("Microsoft Learn: Get-Printer",'https://learn.microsoft.com/en-us/powershell/module/printmanagement/get-printer'),("Microsoft Q&A: IP address of WSD port printers",'https://learn.microsoft.com/en-us/answers/questions/704271/ip-address-of-wsd-port-printers-using-powershell'),("Microsoft Q&A: printer offline and WSD ports",'https://learn.microsoft.com/en-us/answers/a/12132198'),("RFC 2131: Dynamic Host Configuration Protocol",'https://www.rfc-editor.org/rfc/rfc2131'),("RFC 1918: Address Allocation for Private Internets",'https://www.rfc-editor.org/rfc/rfc1918'),("CUPS: Common UNIX Printing System",'https://www.cups.org/'),("CUPS manual page: lpstat",'https://www.kernel.org/doc/man-pages/online/pages/man1/lpstat.1.html'),("Apple Support: add and manage printers on Mac",'https://support.apple.com/kb/PH25081'),("Brother: print the Network Configuration Report",'https://support.brother.com/g/s/id/htmldoc/printer/cv_hll2310d/cee/html/GUID-44BEFA90-16C6-48A6-8A51-4A2D1A14D01F_57.html'),("Brother HL-L2312D user's guide (ManualsLib copy): print the Network Configuration Report",'https://manualslib.com/manual/2686855/Brother-Hl-L2312d.html?page=81'),("HP Support: finding the IP address (HP app, control panel, Information page)",'https://support.hp.com/bg-en/document/ish_6039801-6039767-16'),("Epson Support: how do I obtain my product's IP address",'https://epson.com/faq/SPT_C11CB33201~faq-212719'),("Epson Support: set up Epson Connect from a web browser",'https://epson.com/faq/SPT_ERP-NS~faq-0000c43-shared?faq_cat=faq-topFaqs'),("Canon Support: print the network settings (LAN details)",'https://support.usa.canon.com/kb/articles/en_US/Knowledge/ART163766'),("Canon Support: the Remote UI",'https://support.usa.canon.com/kb/articles/en_US/Knowledge/ART174003'),("Lexmark: finding the IP address of the printer",'https://publications.lexmark.com/publications/lexmark_hardware/CX51x/UG/html/en/finding-ip-address-of-printer-topic.html'),("Atera: how to find a printer IP address (WSD, mDNS and AirPrint behaviour; a vendor blog)",'https://www.atera.com/blog/how-to-find-printer-ip-address/')],
faq_sub='Thirteen questions about finding, keeping and fixing a printer address.',
faq=[("Why would I need my printer's IP address?","You need it to add a printer manually, open its settings page in a browser, fix a printer that shows as offline, or set up printing from a device that cannot find it automatically."),
("Is the printer's IP address the same as my home's public IP address?","No. The printer has a private address that only works inside your network. Your home's public address is shared by all your devices."),
("My printer shows an address starting 169.254. What does that mean?","It means the printer could not get an address from the router and gave itself a link-local one. Check the Wi-Fi or cable connection, restart the printer and router, and confirm DHCP is on."),
("Can I find the printer's IP address from my phone?","Not directly. A phone does not list other devices' addresses. Use the printer maker's app, such as Network Information in the HP app, the printer's own screen or the router's device list. AirPrint often shows only the printer's name."),
("Does a printer's IP address change?","It can. Unless you set a reservation or a static address, the router may assign a new one after a restart or when the lease expires."),
("What if two devices have the same IP address?","Both can lose connectivity at times. Give the printer a DHCP reservation, or set a static address outside the range the router hands out, and keep it unique."),
("Is it safe to expose a printer to the internet?","No. Printers have limited security, so keep them on the private network and do not forward ports to them."),
("What are port 9100 and IPP?","Port 9100 is commonly used for raw printing. IPP is the standard Internet Printing Protocol, defined in RFC 8011, and it normally uses port 631. Both are normally used only on the local network."),
("I replaced my router and printing stopped. Why?","The new router may use a different address range, so the saved printer address no longer matches. Find the new address and re-add the printer."),
("Why does my printer say offline when it is on?","The computer cannot reach it at the saved address. The address may have changed, the printer may be on another network, or the port may be wrong. Ping the printer to tell these apart."),
("Should I use a WSD or a Standard TCP/IP port on Windows?","A Standard TCP/IP port with a fixed address is often more stable, because a WSD port relies on discovery and can lose the device."),
("Can I print without knowing the printer's IP address?","Often yes. A printer that your computer or phone finds on its own appears in the printer list by name, and you can print to it without typing an address. You need the address to add a printer by hand, to open its settings page in a browser, or to fix one that shows as offline."),
("Why does my printer have no IP address?","A printer connected only by USB is not on the network, so it has no IP address. A network printer can show 169.254.x.x or 0.0.0.0 while it is still waiting for an address from the router.")])
